public static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastIndexOfUnixSeparator = filename.lastIndexOf('/');
    int lastIndexOfWindowsSeparator = filename.lastIndexOf('\\');
    if (lastIndexOfUnixSeparator == -1) {
        return lastIndexOfWindowsSeparator;
    }
    if (lastIndexOfWindowsSeparator == -1) {
        return lastIndexOfUnixSeparator;
    }
    return Math.max(lastIndexOfUnixSeparator, lastIndexOfWindowsSeparator);
}

